            assert_eq!(0, cache.len());
            assert_eq!("memory", stmt.query_row([], |r| r.get::<_, String>(1))?);
        }
        assert_eq!(1, cache.len());

        db.set_prepared_statement_cache_capacity(0);
        assert_eq!(0, cache.len());

        {
            let mut stmt = db.prepare_cached(sql)?;
            assert_eq!(0, cache.len());
            assert_eq!("memory", stmt.query_row([], |r| r.get::<_, String>(1))?);
